const only = (() => {
  const i = process.argv.indexOf('--only');
  return i >= 0 ? String(process.argv[i + 1] ?? '') : '';
})();
const onlyKeys = only ? only.split('|').map((k) => k.trim()).filter(Boolean) : [];
// 跑法（2026-10-01，Yolin：平常只跑受影響的突變；全跑只在 Yolin 指定、較大的版本發布前、範圍判斷不出來時）
//   不帶參數      ＝ --affected（v11 §5.18：預設只跑受影響的）：從沒跑過、突變本身改了、依賴範圍裡有檔案改了、執行器改了、
//                 上次沒紅或不算數、上次沒記雜湊（scripts/depgraph.mjs）
//   --full        整套（要明講；全跑只在 Yolin 指定、較大的版本發布前、範圍判斷不出來時，經 Dispatch 排）。
//                 帳本裡「這個 commit 已經算數地跑過、雜湊也沒變」的跳過——中斷後再下同一個指令就是續跑。
//   --never-full  只跑從沒在整套（或補跑）裡跑過的
//   --only <字>   照舊：名稱／檔名／測試名含關鍵字的
//   --limit N     這一次最多跑 N 條（分段）；--dry-run 只列出會跑哪幾條、為什麼，不跑
const argOf = (n) => { const i = process.argv.indexOf(n); return i >= 0 ? String(process.argv[i + 1] ?? '') : null; };
const MODE_FLAGS = ['--affected', '--never-full', '--full'].filter((f) => process.argv.includes(f));
const MODE = only ? 'only' : MODE_FLAGS[0] === '--full' ? 'full' : MODE_FLAGS[0] === '--never-full' ? 'never-full' : 'affected';
const LIMIT = argOf('--limit') === null ? null : Number(argOf('--limit'));
const DRY = process.argv.includes('--dry-run');
// 系統可用記憶體的下限（MB；不給＝不查）。每一條突變開跑前查，低於就收手
const MIN_FREE_MB = argOf('--min-free-mb') === null ? null : Number(argOf('--min-free-mb'));
// 資源紀錄的間隔（秒；2026-10-02 JLPT：60 秒取樣時，只跑幾秒的測試永遠取樣不到，峰值系統性偏低）
const RESLOG_INTERVAL = argOf('--reslog-interval') === null ? 60 : Number(argOf('--reslog-interval'));
const LEDGER_PATH = process.env.MM_LEDGER ? path.resolve(process.env.MM_LEDGER) : path.join(ROOT, LEDGER_FILE);

// 每支測試的逾時（分鐘）。assertaudit 要把整條測試鏈 26 支都跑一遍，2026-10-01 實測約 18 分鐘——
// 原本一律 10 分鐘，它在基準段就被殺掉，指定由它驗的突變從來沒在整套裡跑過（輸出只剩開頭，看不出是逾時）。
// resume-verify：帳本裡每條中位 191 秒、最長 261 秒，10 分鐘只有 2.3 倍（照最長那次算）；調成 15 分鐘＝3.4 倍
// （Dispatch 2026-10-02：餘裕不到 3 倍，逾時就會把慢一點的突變記成不算數＝漏驗；倍數一律用最長那次算）
const TEST_TIMEOUT_MIN = { assertaudit: 45, 'resume-verify': 15 };
// 怎麼結束的要分清楚（scripts/runkind.mjs）：逾時、沒跑起來、被殺不算數；只有斷言失敗才是「紅在斷言」
// 每一次跑測試的 Job 結算（逐一計數與結束核對，2026-10-08）：收尾時彙總，跟取樣的峰值並列
const JOB_SUMS = [];
function runTest(name) {
  const file = path.join(ROOT, 'scripts', `${name}.mjs`);
  // inJob（2026-10-08）：經 jobrun 開——逾時被殺時，測試經 Git Bash 或 detached 開出來的子孫一起被收掉（10-02 正式那場的教訓）
  // finalOf（2026-10-08，第 8 項）：輸出裡要有這支的結算行——被外力停掉的（印過 ✗、回 1，卻沒跑完）判成沒跑完、不算數
  const r = runProgram([file], { cwd: ROOT, timeoutMs: (TEST_TIMEOUT_MIN[name] ?? 10) * 60 * 1000, inJob: true, finalOf: name });
  JOB_SUMS.push({ name, ...parseJobSum(r.out) });
  return r;
}
const tally = { assert: 0, crash: 0, uncounted: [] };

// 突變跑到一半被殺掉時，原始碼會停在改壞的狀態；下一次啟動先還原。
const PENDING = path.join(ROOT, 'scripts/.mutation-pending.json');
// 一次只改一支檔是現在的結構，不是機制保證的：還原紀錄還在（上一支還沒還原）時又要改另一支，拒絕——
// 紀錄只記得一支，第二支會被靜默少記（Dispatch 2026-10-02）。回傳問題字串，空字串＝寫好了。
function writePending(rel, content) {
  if (fs.existsSync(PENDING)) {
    let prev = '（讀不出來）';
    try { prev = JSON.parse(fs.readFileSync(PENDING, 'utf8')).rel; } catch { /* 讀不出來也照樣拒絕，下面的訊息會寫「讀不出來」 */ }
    return `還原紀錄還在（${prev} 還沒還原），拒絕再改 ${rel}——一次只准一支改壞的檔`;
  }
  fs.writeFileSync(PENDING, JSON.stringify({ rel, content }), 'utf8');
  return '';
}
function clearPending() { fs.rmSync(PENDING, { force: true }); }
function recoverPending() {
  if (!fs.existsSync(PENDING)) return null;
  // 紀錄壞掉時硬失敗（2026-10-02，StockDiary 的是「解析失敗就當成沒有紀錄」——還原機制在紀錄壞掉的那一刻就消失了）。
  // 也要擋「JSON 對、欄位不對」：content 不是字串時，以前會把字串 undefined 寫進原始碼檔。紀錄留著不刪，給人看。
  let rec = null;
  try { rec = JSON.parse(fs.readFileSync(PENDING, 'utf8')); } catch (e) {
    console.log(`  ✗ 還原紀錄（scripts/.mutation-pending.json）讀不懂（${String(e.message).slice(0, 80)}）：不知道該還原哪支檔、還原成什麼——請人工確認工作區（git status、git diff），確認後再刪掉那份紀錄`);
    process.exit(1);
  }
  if (!rec || typeof rec.rel !== 'string' || !rec.rel || typeof rec.content !== 'string') {
    console.log(`  ✗ 還原紀錄（scripts/.mutation-pending.json）欄位不對（要有檔名 rel 與原檔內容 content 兩個字串）：不還原、不往下跑——請人工確認工作區，確認後再刪掉那份紀錄`);
    process.exit(1);
  }
  fs.writeFileSync(path.join(ROOT, rec.rel), rec.content, 'utf8');
  clearPending();
  return rec.rel;
}

// 結束或 Ctrl-C（2026-10-02，StockDiary 盤出它那條從沒觸發過）：Node 預設收到 SIGINT 會立刻結束、finally 不跑。
// 掛上處理器之後，訊號要等目前這一支測試結束才處理（同步呼叫期間事件迴圈停著；同一個主控台的 Ctrl-C 也會送到那支測試，它通常先結束）
// → finally 照常還原；處理器自己再照還原紀錄還原一次（紀錄還在才還原），以 130 結束。
// **這條路在本機（Windows）造不出來驗**：node 送不出真的 SIGINT／Ctrl-C 給別的程序（process.kill 的 SIGINT 在 Windows 等於直接結束）。
// 所以它不算一道已驗證的防線；真正擋住壞檔的是「下次啟動先還原」（resume-verify 真的殺程序驗過）與推送閘門的第零關之零（回 7）。
for (const sig of ['SIGINT', 'SIGTERM', 'SIGHUP']) {
  process.on(sig, () => { try { const r = recoverPending(); if (r) console.log(`  · 收到 ${sig}：已還原 ${r}`); } finally { process.exit(130); } });
}
const refuse = (msg) => { ok(false, msg); done('mutationtest'); process.exit(1); };
// 「是不是改壞前的內容」只比內容、不比行尾：人工用 git 還原時，行尾可能被 git 的設定換成 CRLF（2026-10-02 resume-verify 撞到），
// 逐位元組比會把已經還原好的檔判成「不是原樣」、永遠拒絕。突變不會只改行尾，所以這樣不會放過改壞的檔。
const eolHash = (text) => contentHash(String(text).replace(/\r\n/g, '\n'));

section('前置');
const recovered = recoverPending();
if (recovered) note(`上一次被中斷，已還原 ${recovered}`);
// 帳本先讀進來：兩處紀錄（磁碟上的還原紀錄、帳本的 inflight）要一致（Dispatch 2026-10-02）
const ledger = fs.existsSync(LEDGER_PATH) ? JSON.parse(fs.readFileSync(LEDGER_PATH, 'utf8')) : emptyLedger();
let inflightCleared = false;
{
  const inf = ledger.inflight ?? null;
  // 還原那一步跑完，還原紀錄卻還在：還原本身沒成功——不往下跑（往下跑會把改壞的檔當原檔備份）
  if (fs.existsSync(PENDING)) refuse(`還原紀錄（scripts/.mutation-pending.json）還在、卻沒有還原${inf ? `（帳本記著第 ${inf.run} 次開跑改 ${inf.file}）` : ''}——請人工確認工作區`);
  if (recovered) {
    if (inf && inf.file !== recovered) refuse(`兩處紀錄對不上：磁碟上的還原紀錄還原的是 ${recovered}，帳本記的是第 ${inf.run} 次開跑改 ${inf.file}——請人工確認工作區`);
    if (inf) { ledger.inflight = null; inflightCleared = true; }
  } else if (inf) {
    const full = path.join(ROOT, inf.file);
    const now = fs.existsSync(full) ? eolHash(fs.readFileSync(full, 'utf8')) : null;
    if (now !== inf.origHash) {
      refuse(`上一次中斷過、還原紀錄卻不見了：帳本記著第 ${inf.run} 次開跑（突變「${inf.mutation}」）改壞 ${inf.file}，沒有收尾；磁碟上的還原紀錄（scripts/.mutation-pending.json）不在，而且 ${inf.file} 現在跟改壞前的內容不同——不能把它當原檔，請人工確認工作區（例如 git diff -- ${inf.file}）`);
    }
    // 檔案已經是改壞前的內容：中斷剛好落在「刪掉還原紀錄」與「清掉帳本那一筆」之間，檔案沒事
    note(`帳本記著第 ${inf.run} 次開跑（突變「${inf.mutation}」）沒有收尾，但 ${inf.file} 的內容雜湊等於改壞前——當成已還原，繼續`);
    ledger.inflight = null; inflightCleared = true;
  }
}
// 參數彼此衝突、--limit 不是正整數：停下來，不猜使用者要哪一種
const argProblems = [];
if (MODE_FLAGS.length > 1 || (only && MODE_FLAGS.length)) argProblems.push('--only、--affected、--never-full、--full 只能選一個');
if (LIMIT !== null && !(Number.isInteger(LIMIT) && LIMIT > 0)) argProblems.push('--limit 要接正整數');
if (MIN_FREE_MB !== null && !(MIN_FREE_MB >= 1)) argProblems.push('--min-free-mb 要接正的 MB 數');
if (!(RESLOG_INTERVAL >= 1 && RESLOG_INTERVAL <= 600)) argProblems.push('--reslog-interval 要接 1 到 600 之間的秒數');
eq(argProblems, [], '參數沒有衝突');
if (argProblems.length) { done('mutationtest'); process.exit(1); }

// 雜湊一律在**還原之後、改壞任何檔之前**算（上面的 recoverPending 先跑）：算的是沒有突變的那一份
const git = (args) => execFileSync('git', args, { cwd: ROOT, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
let COMMIT = null; let repoFiles = null; let dirtyFiles = [];
try {
  COMMIT = git(['rev-parse', '--short=12', 'HEAD']).trim();
  // 執行器自己會寫的兩支（帳本、整套基準清單）不算改動
  dirtyFiles = git(['-c', 'core.quotepath=off', 'status', '--porcelain', '--untracked-files=no']).split('\n').filter((l) => l.trim())
    .map((l) => l.slice(3)).filter((f) => f !== LEDGER_FILE && f !== LASTFULL_FILE);
  repoFiles = git(['-c', 'core.quotepath=off', 'ls-files', '-c', '-o', '--exclude-standard', '-z']).split('\0').filter(Boolean);
} catch (e) {
  refuse(`git 取不到（${String(e.message).split('\n')[0].slice(0, 80)}）：「工作區要等於 HEAD」的護欄檢查不了，拒絕執行`);
}
// 被殺的那一層（例：doctest 逾時被 Job 收掉）留下的 worktree：建立者已死的先收掉（worktreesweep.mjs）；只列不跑時不動
if (!DRY) sweepWorktrees(ROOT, { log: (s) => note(s.replace(/^· /, '')) });
// 護欄一（Dispatch 2026-10-02）：開跑前工作區必須等於 HEAD——上一次被殺掉留下的壞檔，不能被這一次當成原檔備份起來。
// --only 例外（寫新斷言的流程是「改程式 → --only 證明會紅 → 才 commit」，那時工作區本來就不等於 HEAD），另有下面的目標檔檢查。
// --dry-run 只列不改檔：照常列出，只註明工作區有改動
if (dirtyFiles.length && DRY) note(`（只列不跑）工作區不等於 HEAD：${dirtyFiles.join('、')}——真的跑的時候會拒絕`);
if (dirtyFiles.length && MODE !== 'only' && !DRY) refuse(`工作區不等於 HEAD，拒絕執行（${MODE}）：${dirtyFiles.join('、')}——先 commit 或還原；若是上一次中斷留下的，先確認那幾支是不是改壞的版本`);
if (dirtyFiles.length) COMMIT += '+dirty';
const fileHashCache = new Map();
const fileHash = (rel) => {
  if (!fileHashCache.has(rel)) {
    const full = path.join(ROOT, rel);
    fileHashCache.set(rel, fs.existsSync(full) && fs.statSync(full).isFile() ? contentHash(fs.readFileSync(full)) : null);
  }
  return fileHashCache.get(rel);
};
const srcCache = new Map();
const readSrc = (rel) => { if (!srcCache.has(rel)) srcCache.set(rel, fs.readFileSync(path.join(ROOT, rel), 'utf8')); return srcCache.get(rel); };
const RUNNER_HASH = runnerHash(repoFiles, readSrc, fileHash);
const curCache = new Map();
const curOf = (m) => {
  if (!curCache.has(m.name)) {
    const sc = scopeFor(m, repoFiles, readSrc);
    curCache.set(m.name, { defHash: mutationDefHash(m, TEST_TIMEOUT_MIN[m.test] ?? null), depHash: scopeHash(sc.files, fileHash), runnerHash: RUNNER_HASH, scope: sc.kind, scopeReasons: sc.reasons });
  }
  return curCache.get(m.name);
};
const ledgerBad = ledgerProblems(ledger);
eq(ledgerBad, [], `帳本 ${path.relative(ROOT, LEDGER_PATH)} 讀得懂`);
if (ledgerBad.length) { done('mutationtest'); process.exit(1); }
{
  const orph = ledgerOrphans(MUTATIONS.map((m) => m.name), ledger);
  if (orph.notInList.length) note(`帳本有、突變清單已經沒有的 ${orph.notInList.length} 條（被刪或改名）：${orph.notInList.slice(0, 5).join('、')}${orph.notInList.length > 5 ? '…' : ''}`);
}
const LEDGER_WRITABLE = COMMIT !== null || !!process.env.MM_LEDGER;
if (!LEDGER_WRITABLE) note('這裡不是 git repo：結果只記在記憶體裡，不寫帳本檔');
ledger.runSeq = (ledger.runSeq ?? 0) + 1;
const RUN_SEQ = ledger.runSeq;
function saveLedger() {
  if (!LEDGER_WRITABLE) return;
  const tmp = `${LEDGER_PATH}.tmp`;
  fs.writeFileSync(tmp, `${JSON.stringify(ledger, null, 1)}\n`, 'utf8');
  fs.renameSync(tmp, LEDGER_PATH);
}
if (inflightCleared) saveLedger();

const whyRun = new Map();
let SELECTED;
if (MODE === 'only') SELECTED = MUTATIONS.filter((m) => [m.name, m.file, m.test].some((s) => onlyKeys.some((k) => s.includes(k))));
else if (MODE === 'never-full') {
  const never = new Set(neverFullNames(MUTATIONS.map((m) => m.name), ledger));
  SELECTED = MUTATIONS.filter((m) => never.has(m.name));
} else if (MODE === 'affected') {
  SELECTED = MUTATIONS.filter((m) => { const r = rerunReasons(ledger.entries[m.name], curOf(m)); if (r.length) whyRun.set(m.name, r); return r.length > 0; });
} else {
  // 整套：這個 commit 上已經算數地跑過、雜湊也沒變的跳過（續跑）
  SELECTED = MUTATIONS.filter((m) => !doneAt(ledger.entries[m.name], COMMIT, curOf(m)));
}
// --test <a|b>（2026-10-02，Dispatch 排的順序要逐段跑：照每機器小時驗到的條數，先跑便宜的）：
// 在上面選好的母體裡，只留指定測試的（測試名完全相同，不是子字串）。指定的測試名在清單裡一條都沒有＝打錯字，停
const TEST_FILTER = argOf('--test');
if (TEST_FILTER !== null) {
  const want = TEST_FILTER.split('|').map((s) => s.trim()).filter(Boolean);
  const known = new Set(MUTATIONS.map((m) => m.test));
  const unknown = want.filter((t) => !known.has(t));
  if (!want.length || unknown.length) refuse(`--test 指定的測試在突變清單裡一條都沒有：${unknown.join('、') || '（空的）'}`);
  SELECTED = SELECTED.filter((m) => want.includes(m.test));
}
const CANDIDATES = SELECTED.length;
const CANDIDATE_SET = new Set(SELECTED.map((m) => m.name));
// 只差空白或行尾的突變：改了等於沒改，而執行器判斷「是不是原樣」只比內容——跑了會顯示通過、什麼都沒驗到（checkmutations.whitespaceOnly）
{
  const wsOnly = SELECTED.filter((m) => whitespaceOnly(m.find, m.replace));
  if (wsOnly.length) refuse(`突變的原文與改壞後只差空白或行尾，拒絕執行：${wsOnly.map((m) => `「${m.name}」（${m.file}）`).join('、')}`);
}
// 護欄一的 --only 版（Dispatch 2026-10-02）：工作區可以有改動，但這次要改的目標檔不能已經是「改壞後」的樣子——
// 目標檔含這條突變的替換字串、HEAD 的那一版卻沒有，多半是上一次中斷留下的壞檔；拿它當原檔備份，「還原」就會把壞檔還原回去。
if (MODE === 'only') {
  const leftovers = [];
  for (const m of SELECTED) {
    if (!m.replace || !m.replace.trim()) continue;
    const full = path.join(ROOT, m.file);
    const nowText = fs.existsSync(full) ? fs.readFileSync(full, 'utf8') : '';
    if (!nowText.includes(m.replace)) continue;
    let headText = '';
    try { headText = git(['show', `HEAD:${m.file}`]); } catch { headText = ''; }      // HEAD 沒有這支檔：當成空的（新檔含替換字串一樣可疑）
    if (!headText.includes(m.replace)) leftovers.push(`${m.file}（突變「${m.name}」的替換字串已經在檔裡，HEAD 沒有）`);
  }
  if (leftovers.length) refuse(`要改的目標檔看起來已經是改壞後的樣子，拒絕執行：${leftovers.join('、')}——先確認那幾支是不是上一次中斷留下的`);
}
if (LIMIT !== null) SELECTED = SELECTED.slice(0, LIMIT);
const TESTS = [...new Set(SELECTED.map((m) => m.test))];
const missingTests = TESTS.filter((t) => !fs.existsSync(path.join(ROOT, 'scripts', `${t}.mjs`)));
eq(missingTests, [], '每條突變指定的測試檔都存在');
note(`這一次：${taiwanToday()}、commit ${COMMIT}、跑法 ${MODE}`);   // 證據檔（scripts/evidence.mjs）從這一行取日期與 commit
note(`資源紀錄的取樣間隔：每 ${RESLOG_INTERVAL} 秒（比最短的那支測試還長時，那支的程序可能一次都取樣不到，峰值會偏低）`);
const pickedLine = `選了 ${SELECTED.length} 條突變（共 ${MUTATIONS.length}）${only ? `，關鍵字「${only}」` : ''}${TEST_FILTER !== null ? `，只留測試「${TEST_FILTER}」` : ''}；跑法 ${MODE}${LIMIT !== null ? `，這一段最多 ${LIMIT} 條（符合的有 ${CANDIDATES} 條）` : ''}`;
// --only 對不到任何一條是打錯字（F1-11）；受影響／從沒全跑過／整套續跑選到 0 條，是「沒有要跑的」，不是錯
if (MODE === 'only') ok(SELECTED.length > 0, pickedLine);
else note(pickedLine);
if (MODE === 'affected') {
  const tally0 = {};
  for (const r of whyRun.values()) for (const x of r) tally0[x] = (tally0[x] ?? 0) + 1;
  note(`受影響的理由統計：${Object.entries(tally0).map(([k, v]) => `${k} ${v} 條`).join('、') || '（沒有）'}；沿用上次結果 ${MUTATIONS.length - CANDIDATES} 條`);
}
// 「為什麼要全跑」：選到的裡面，依賴範圍是整個 repo 的（判斷不出範圍），理由依檔案彙總
const repoWhy = new Map();
for (const m of SELECTED) for (const r of new Set(curOf(m).scopeReasons ?? [])) repoWhy.set(r, (repoWhy.get(r) ?? 0) + 1);
if (MODE !== 'only') note(`選到的 ${SELECTED.length} 條裡，依賴範圍判斷不出、算整個 repo 的 ${SELECTED.filter((m) => curOf(m).scope === 'repo').length} 條${repoWhy.size ? `；理由（前 5）：${[...repoWhy].sort((a, b) => b[1] - a[1]).slice(0, 5).map(([r, n]) => `${r}（${n} 條）`).join('；')}` : ''}`);
if (DRY) {
  const scopes = {};
  for (const m of MUTATIONS) { const k = curOf(m).scope; scopes[k] = (scopes[k] ?? 0) + 1; }
  note(`依賴範圍的種類：${Object.entries(scopes).map(([k, v]) => `${k} ${v} 條`).join('、')}`);
  for (const m of SELECTED) note(`會跑：【${m.test}】${m.name}${whyRun.has(m.name) ? `（${whyRun.get(m.name).join('、')}）` : ''}`);
  // 跳過的也逐條列理由（v11 §5.18 第 2 點）
  const picked = new Set(SELECTED.map((m) => m.name));
  for (const m of MUTATIONS) {
    if (picked.has(m.name)) continue;
    const l = ledger.entries[m.name]?.last;
    const why = CANDIDATE_SET.has(m.name) ? '跳過：超過 --limit，留給下一段'
      : MODE === 'affected' ? `沿用：上次 ${l?.date}、${l?.commit}、${l?.red ? '紅' : '沒紅'}，突變本身、依賴範圍、執行器都沒變`
      : MODE === 'never-full' ? `跳過：已經在整套或補跑裡跑過（${ledger.entries[m.name]?.lastFull?.date}、${ledger.entries[m.name]?.lastFull?.commit}）`
        : MODE === 'full' ? '跳過：這個 commit 已經算數地跑過、雜湊沒變（續跑）'
          : '跳過：關鍵字沒對到';
    note(`不跑：【${m.test}】${m.name}——${why}`);
  }
  done('mutationtest');
  process.exit(0);
}

// 資源紀錄（共用慣例 v11 §5.19）：會跑很久的（選到 10 條以上，或明講 --reslog）每 60 秒記一行程序數與記憶體到 .logs/
let reslog = null; let reslogFile = null;
if (SELECTED.length >= 10 || process.argv.includes('--reslog')) {
  // 在 worktree 裡跑整套時，MM_LOGDIR 指回主 repo 的 .logs/（worktree 刪掉，紀錄不跟著消失；同 MM_LEDGER）
  const logDir = process.env.MM_LOGDIR ? path.resolve(process.env.MM_LOGDIR) : path.join(ROOT, '.logs');
  reslogFile = path.join(logDir, `${taiwanToday()}_${(COMMIT ?? 'nogit').replace('+', '-')}_${MODE}_run${RUN_SEQ}_reslog.log`);   // 帶第幾次開跑（2026-10-02：同一天同一個 commit 跑好幾次，以前全寫進同一個檔、峰值是累積的）
  fs.mkdirSync(path.dirname(reslogFile), { recursive: true });
  reslog = spawn(process.execPath, [path.join(ROOT, 'scripts/reslog.mjs'), '--root', String(process.pid), '--out', reslogFile, '--interval', String(RESLOG_INTERVAL)], { stdio: 'ignore' });
  note(`資源紀錄：${path.relative(ROOT, reslogFile)}（每 ${RESLOG_INTERVAL} 秒一行；同時最多 ${MAX_WORKERS} 個工作程序是共用上限，本執行器一次只跑一支測試）`);
}

section('基準：沒有突變時全部要綠');
let baselineOk = true;
for (const t of TESTS) {
  const r = runTest(t);
  // 沒有任何 ✗ 的失敗＝子行程根本沒跑完（崩潰、逾時、被殺），那時候要看的是尾端輸出，不是斷言。
  const fails = r.out.split('\n').filter((l) => l.trimStart().startsWith('✗')).slice(0, 5);
  ok(r.passed, `基準 ${t} 通過`, r.passed ? '' : [`（${KIND_LABELS[r.kind]}，${r.seconds} 秒）`, ...(fails.length ? fails : r.out.split('\n').filter(Boolean).slice(-8))].join('\n      '));
  if (!r.passed) baselineOk = false;
}

// 預期需要複審（2026-10-02 A＋）：這一次要跑的、帶 expect 的突變裡，測試的斷言母體跟戳記不一樣的——只報、不擋。
// 跑出來的「紅在預期那一條」照樣算，但它的 expect 寫的時候還沒有後來新增的斷言，要找時間複審（scripts/assertregistry.mjs）
{
  const rv = reviewNeeded(SELECTED, loadStamps(ROOT), readTestFrom(ROOT));
  section('預期需要複審');
  note(`這一次要跑的 ${SELECTED.length} 條裡，帶 expect 的 ${SELECTED.filter((m) => m.expect != null).length} 條；母體跟戳記不一樣、要複審的 ${rv.length} 條`);
  for (const x of rv) note(`預期需要複審：${x.test}｜${x.name}｜${x.why}`);
  // 預期清單過期的前置，通過時也印（2026-10-02，StockDiary：通過時一行不印，「0 個過期」就只能從「沒看到報錯」推出來）
  const withE = SELECTED.filter((m) => m.expect != null);
  const readR = (rel) => (fs.existsSync(path.join(ROOT, rel)) ? fs.readFileSync(path.join(ROOT, rel), 'utf8') : null);
  const staleE = withE.filter((m) => expectProblems(m, readR).length > 0);
  note(`預期清單過期的前置：這一次帶 expect 的 ${withE.length} 條，查了 ${withE.length} 條（expect 在測試原始碼裡找不找得到），找不到 ${staleE.length} 條${staleE.length ? `（逐條裡另外報「預期清單過期」：${staleE.map((m) => m.name).join('、')}）` : ''}`);
}

let ran = 0; // 實際跑到（改壞、跑測試、還原）的條數；整套完整跑完才寫 mutation-lastfull.json
if (baselineOk) {
  section('逐條突變');
  for (const m of SELECTED) {
    // 可用記憶體下限（--min-free-mb；Dispatch 2026-10-02：筆電前幾天連續當機兩次，掉到下限以下就收手、不硬跑）。
    // 在改壞任何檔之前查：停下時工作區是乾淨的，沒有還原紀錄
    if (MIN_FREE_MB !== null) {
      const freeMB = Math.round(os.freemem() / 1048576);
      if (freeMB < MIN_FREE_MB) {
        const left = SELECTED.length - SELECTED.indexOf(m);
        ok(false, `停下：系統可用記憶體 ${freeMB} MB，低於下限 ${MIN_FREE_MB} MB`, `「${m.name}」與之後共 ${left} 條沒跑（收手，不是那幾條失敗；用 scripts/runprogress.mjs 看三類）`);
        break;
      }
    }
    const full = path.join(ROOT, m.file);
    const original = fs.readFileSync(full, 'utf8');
    const count = original.split(m.find).length - 1;
    const cur = curOf(m);
    const record = (extra) => {
      recordRun(ledger, m.name, { date: taiwanToday(), commit: COMMIT ?? '0000000', mode: MODE, defHash: cur.defHash, depHash: cur.depHash, runnerHash: cur.runnerHash, scope: cur.scope, ...extra });
      saveLedger();
    };
    if (count !== 1) {
      record({ kind: 'stale', counted: true, red: false, seconds: 0 });
      ok(false, `【${m.test}】${m.name}`, `要改的程式碼在 ${m.file} 出現 ${count} 次（要剛好 1 次）—— 這條突變過期了`);
      continue;
    }
    // 預期清單過期（2026-10-02，四個專案同一天各踩一次）：expect 在測試的原始碼裡已經找不到，跑下去只會得到「紅錯地方」，
    // 被讀成程式有問題。開跑前先擋、用獨立的訊息；不改壞任何檔、帳本記成不算數（下次要再挑）
    const exP = expectProblems(m, (rel) => (fs.existsSync(path.join(ROOT, rel)) ? fs.readFileSync(path.join(ROOT, rel), 'utf8') : null));
    if (exP.length) {
      record({ kind: 'stale', counted: false, red: false, seconds: 0 });
      ok(false, `【${m.test}】${m.name}`, `預期清單過期：${exP.join('；')}（沒有跑，先更新這一條的 expect）`);
      continue;
    }
    const mutated = original.replace(m.find, m.replace);
    // 兩處紀錄（Dispatch 2026-10-02）：先在帳本記「第 N 次開跑、改哪一支、原檔雜湊」，再寫磁碟上的還原紀錄；
    // 還原後兩處都清掉。只有一份紀錄的話，紀錄被刪掉時無從察覺；兩處對不上，下次啟動就會拒絕（見「前置」）。
    ledger.inflight = { run: RUN_SEQ, mutation: m.name, file: m.file, origHash: eolHash(original), at: new Date().toISOString() };
    saveLedger();
    const pendingProblem = writePending(m.file, original);
    if (pendingProblem) { ledger.inflight = null; saveLedger(); refuse(pendingProblem); }
    fs.writeFileSync(full, mutated, 'utf8');
    let result;
    try {
      result = runTest(m.test);
    } finally {
      fs.writeFileSync(full, original, 'utf8');
      clearPending();
      ledger.inflight = null;
    }
    const restored = fs.readFileSync(full, 'utf8') === original;
    // 測試沒有完整跑完（逾時、被殺、沒跑起來）：不能拿來判斷這條突變有沒有被抓到——不算紅、也不算綠，要重跑
    if (UNCOUNTED_KINDS.has(result.kind)) {
      tally.uncounted.push(m.name);
      record({ kind: result.kind, counted: false, red: false, seconds: result.seconds });
      ok(false, `【${m.test}】${m.name}`, `不算數：${m.test} ${KIND_LABELS[result.kind]}（${result.seconds} 秒），這條突變沒有被驗到，要重跑${!restored ? `；而且 ${m.file} 沒有還原成功！` : ''}`);
      continue;
    }
    ran += 1; // 「不算數」的不計入：一輪裡有沒驗到的突變，就不能寫成「整套完整跑完」
    if (result.kind === 'assert') tally.assert += 1;
    // 崩潰（crash）2026-10-02 起列在不算數裡（runkind.UNCOUNTED_KINDS），上面那一段就接走了，走不到這裡
    // expect（選填）：紅的一定要是這一條。改食譜檔或 foodtags.json 的突變一定會讓「recipes.json 是最新的」紅，
    // 只看有沒有紅的話，新斷言有沒有在檢查東西根本看不出來（2026-09-19 補早餐時發現）。
    // 只認「以 ✗ 開頭」的行（2026-10-02）：以前只看「那一行有沒有 ✗ 這個字」，通過的行（✓ …）訊息裡提到 ✗ 也會被當成「紅在這一條」
    // ——例：「✓ R2 回傳非 0、輸出裡有 ✗ → 斷言失敗」、resume-verify 的「✓ 護欄 …（回 1；✗ 上一次中斷過…）」。
    const failLine = (l) => l.trimStart().startsWith('✗');
    const failed = result.out.split('\n').filter(failLine).map((l) => l.trim());
    const expectHits = m.expect ? failed.filter((l) => l.includes(m.expect)) : [];
    const expectHit = !m.expect || expectHits.length > 0;
    // 紅的是不是預期那一種（v11 §5.18 第 4 點）：有 expect 的記比對結果；沒寫 expect 的記 null（判不出紅錯地方，照實記）
    // failed／expectHits 記條數（2026-10-02，StockDiary 挖出來的：只在判錯時印實際紅了哪幾條，判對時就無法稽核
    // 「expect 對到好幾條、隨便哪一條紅都算過」）
    record({ kind: result.kind, counted: true, red: !result.passed && expectHit && restored, expectMatched: m.expect ? (!result.passed && expectHit) : null, failed: failed.length, expectHits: m.expect ? expectHits.length : null, seconds: result.seconds });
    ok(!result.passed && expectHit && restored, `【${m.test}】${m.name}`,
      !restored ? `${m.file} 沒有還原成功！`
        : result.passed ? `改壞之後 ${m.test} 居然還是綠的 —— 對應的斷言沒有在檢查東西。${m.why}`
          : `${m.test} 紅了，但紅的不是含「${m.expect}」的那一條 —— 對應的斷言沒有在檢查東西。${m.why}\n      實際紅的（前 4 行 ✗）：${result.out.split('\n').filter(failLine).slice(0, 4).map((l) => l.trim().slice(0, 160)).join('｜') || '（輸出裡沒有 ✗）'}`);
    // 判對、判錯都印實際紅了哪幾條。用說明行（開頭「  · 」）：這一行裡會出現 ✗，但不在行首，不會被當成失敗的斷言
    if (!result.passed) {
      const show = (arr) => `${arr.slice(0, 4).map((l) => l.slice(0, 120)).join('｜')}${arr.length > 4 ? `…（另 ${arr.length - 4} 條）` : ''}`;
      note(`實際紅了 ${failed.length} 條${m.expect ? `；含「${m.expect}」的 ${expectHits.length} 條${expectHits.length > 1 ? '（expect 對到不只一條斷言，看是不是有歧義）' : ''}` : '；沒寫 expect，判不出紅在哪一種'}：${show(m.expect && expectHits.length ? expectHits : failed)}`);
    }
  }
  note(`結束方式統計：情境成立 ${tally.assert} 條（紅在斷言＝完整跑完、某條斷言印出失敗）；情境未成立、不算數 ${tally.uncounted.length} 條（逾時／被殺／沒跑起來／崩潰／宣告情境未成立）${tally.uncounted.length ? `：${tally.uncounted.join('、')}` : ''}`);
} else {
  note('基準沒過，不跑突變（先把測試修綠）');
}

// 不帶 --only、每一條都跑到了 → 重寫「上次整套」的基準清單（docs/SPEC_sincefull_按名稱計數.md）。
// 帶 --only、基準沒過、中途被殺掉，都不會走到這裡寫檔。分段補跑的由人確認後用 npm run sincefull -- --record-full。
// 分段跑（--limit、中斷後續跑）時，這一段的 ran 不會等於總數；改看帳本：每一條在這個 commit 上都算數地跑過、雜湊都是現在的，才算整套跑完
// （scripts/depgraph.mjs fullComplete：少一條、雜湊對不上、不算數的，都不算）。
const fc = MODE === 'full' && baselineOk ? fullComplete(MUTATIONS.map((m) => m.name), ledger, COMMIT, (n) => curOf(MUTATIONS.find((m) => m.name === n))) : { complete: false, missing: [] };
if (MODE === 'full' && baselineOk && !fc.complete) note(`整套還沒收齊：這個 commit 上還有 ${fc.missing.length} 條沒有算數的結果（再下同一個指令會接著跑）：${fc.missing.slice(0, 10).join('、')}${fc.missing.length > 10 ? `…（另 ${fc.missing.length - 10} 條）` : ''}`);
if (MODE === 'full' && baselineOk && fc.complete) note(`整套收齊：${MUTATIONS.length} 條在 ${COMMIT} 上都有算數的結果`);
if ((MODE === 'full' && shouldRecordFull({ only, ran, total: MUTATIONS.length })) || fc.complete) {
  writeLastFull(path.join(ROOT, LASTFULL_FILE), { date: taiwanToday(), version: currentVersion(ROOT), names: MUTATIONS.map((m) => m.name) });
  note(`整套完整跑完：已重寫 ${LASTFULL_FILE}（${MUTATIONS.length} 條）。記得把 STATUS「上次突變整套」那一行改成同樣的日期、版本、條數`);
}

if (reslog) {
  // 收尾前再記一行（短於 60 秒的也至少有開頭與結尾兩行），然後收掉紀錄程序、讀峰值
  try { fs.appendFileSync(reslogFile, `${execFileSync(process.execPath, [path.join(ROOT, 'scripts/reslog.mjs'), '--once', '--root', String(process.pid)], { encoding: 'utf8' }).trim()}\n`); } catch (e) { note(`收尾那一行資源紀錄取不到：${String(e.message).slice(0, 80)}（峰值只算前面記到的行）`); }
  reslog.kill();
  const pk = peakOf(fs.existsSync(reslogFile) ? fs.readFileSync(reslogFile, 'utf8') : '');
  note(`資源紀錄的峰值：工作程序 ${pk.lines ? pk.peakWorkers : '（沒有記到任何一行）'}、合計記憶體 ${pk.lines ? `${pk.peakMB} MB` : '—'}、系統可用最低 ${pk.minFreeMB ?? '—'} MB（${pk.lines} 行${pk.unreadable ? `、取不到程序表 ${pk.unreadable} 行` : ''}；${path.relative(ROOT, reslogFile)}）`);
  if (pk.lines && pk.peakWorkers > MAX_WORKERS) note(`⚠ 峰值 ${pk.peakWorkers} 個工作程序，超過共用上限 ${MAX_WORKERS}（v11 §5.19）`);
}

// 逐一計數與結束核對（2026-10-08，第 7 項；v11 §5.19「兩種峰值並列印出」）：每一次跑測試的 Job 結算彙總，印在取樣峰值旁邊。
// 定義不同要講明：Job 裡算的是全部程序（含 jobrun 自己、conhost、Git Bash 的中間程序、瀏覽器子程序），取樣算的是「工作程序」——
// 兩個峰值的差距不全是取樣漏掉的。開、收各自加總，差值照印（通知不保證送達，可能是負的）；沒有結算的次數另外數，不當成 0
if (JOB_SUMS.length) {
  const got = JOB_SUMS.filter((s) => s.ok);
  // 峰值只取可信的那幾次：有 stale（已經不在、沒收到結束通知）的那一次只加不減、峰值偏高卻看起來合理——作廢，不拿來比大小
  const voided = got.filter((s) => !s.peakOk);
  const top = got.filter((s) => s.peakOk).reduce((a, s) => (!a || s.peak > a.peak ? s : a), null);
  const ST = got.reduce((a, s) => a + s.stale, 0);
  const S = got.reduce((a, s) => a + s.started, 0); const E = got.reduce((a, s) => a + s.ended, 0);
  const leftovers = got.filter((s) => s.leftOthers !== 0);
  const L = got.reduce((a, s) => a + s.leftOthers, 0);
  note(`逐一計數（Job 結算；同一個 Job 裡同時存在的全部程序，跟取樣的「工作程序」定義不同）：跑測試 ${JOB_SUMS.length} 次，有結算 ${got.length} 次、沒有 ${JOB_SUMS.length - got.length} 次${got.length < JOB_SUMS.length ? `（${[...new Set(JOB_SUMS.filter((s) => !s.ok).map((s) => s.why))].slice(0, 3).join('；')}）` : ''}`
    + `；峰值作廢 ${voided.length} 次（結算時已經不在、卻沒收到結束通知的合計 ${ST} 支——只加不減，峰值偏高卻看起來合理，不報${voided.length ? `；在 ${voided.slice(0, 3).map((s) => `${s.name}（${s.stale} 支；${s.stalemix}）`).join('、')}` : ''}）`
    + `；峰值（只取可信的 ${got.length - voided.length} 次）${top ? `${top.peak}（${top.name}，那一刻 ${top.peakmix}；**名字只當參考、總數才準**：名字是程序進 Job 那一刻的，Git Bash 先分叉出 bash 再換成目標，sleep 常被記成 bash）` : `—（${got.length ? '全部作廢' : '沒有結算'}）`}`
    + `；開 ${S}、收 ${E}、差 ${S - E}（照印，不截成 0：Windows 的這些通知不保證送達，開收不一致是正常現象；截成 0，真正的洩漏就跟正常的誤差長得一樣）；測試結束時還留在 Job 裡的（不含 jobrun 自己）合計 ${L} 支${leftovers.length ? `，在 ${leftovers.slice(0, 5).map((s) => `${s.name}（${s.leftOthers}；${s.left}）`).join('、')}——Job 關閉時被收掉` : ''}`);
}

done('mutationtest');